	var main := await instantiate_main_scene()
	if not check("main_ok", main != null, "La scena principale deve aprirsi correttamente"):
		return
	var enemy := find_by_name(main, "Enemy") as CharacterBody2D
	if not check("enemy_ok", enemy != null, "Serve il nodo Enemy nella scena"):
		return
	var agent := find_by_class(enemy, "NavigationAgent2D") as NavigationAgent2D
	if not check("agent_ok", agent != null, "Enemy deve contenere NavigationAgent2D"):
		return
	# Mettiamo il nemico in RETURN
	enemy.set("current_state", 2) # State.RETURN
	var marker := find_by_name(main, "PointA") as Marker2D
	if marker != null:
		enemy.global_position = Vector2(300, 200)
		await wait_physics_frames(15)
		check("return_velocity", enemy.velocity.length() > 0.0 or agent.is_navigation_finished(), "In stato RETURN il nemico deve avere velocità non nulla verso il waypoint")

